-- Mensaje 80 · Lo que califica cada boss, el FFF con su regla, y el 2.8 como "La Mala Experiencia al Llegar".
-- Decisiones de Emilio (14-oct-2026). El trigger validar_practice_script revisa cada guion al escribirlo.
-- Cada nodo se actualiza solo si está en la versión esperada; los chequeos del final abortan si algo no quedó.

-- 1. Reglas nuevas (sus citas existen en el Cerebro vigente).
INSERT INTO public.reglas (id, paso, tipo, canal, procedencia, resumen, cita_cerebro, severidad_default) VALUES ('blocks.mala_experiencia_al_llegar', 2, 'herramienta', 'universal', 'CAMPO', $v$Si el cliente saca una mala experiencia al llegar, no es un bloqueo: se acepta en serio, se da el motivo real de la visita y se regresa al diagnóstico con una pregunta.$v$, $v$no es un bloqueo para atravesar con AIR: es una preocupación real y se maneja como objeción$v$, NULL)
  ON CONFLICT (id) DO UPDATE SET resumen = EXCLUDED.resumen, cita_cerebro = EXCLUDED.cita_cerebro, paso = EXCLUDED.paso, tipo = EXCLUDED.tipo, updated_at = now();
INSERT INTO public.reglas (id, paso, tipo, canal, procedencia, resumen, cita_cerebro, severidad_default) VALUES ('impulse.factores', 4, 'herramienta', 'universal', 'FUENTE', $v$Sube el impulso con los factores de FUJPIG (miedo a la pérdida, urgencia, efecto Jones, poder de asumir, indiferencia, avaricia), siempre reales y comprobables.$v$, $v$El impulso es otra palabra para la emoción$v$, NULL)
  ON CONFLICT (id) DO UPDATE SET resumen = EXCLUDED.resumen, cita_cerebro = EXCLUDED.cita_cerebro, paso = EXCLUDED.paso, tipo = EXCLUDED.tipo, updated_at = now();

-- 2. Skills nuevos, y el "reencuadre" pasa a llamarse FFF con su regla (antes apuntaba a la de RRR).
INSERT INTO public.skills (id, code, name, short_description, category, world_id_introduced, skill_type, decay_half_life_days, requires_audio, status, regla_id) VALUES ('blocks.mala_experiencia', 'S-070', $v$La Mala Experiencia al Llegar$v$, $v$Cuando el cliente ya trae una mala experiencia, no es un bloqueo: la escuchas en serio, das el motivo real de tu visita y regresas a preguntar.$v$, 'blocks', 2, 'tecnica', 180, false, 'active', 'blocks.mala_experiencia_al_llegar')
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, short_description = EXCLUDED.short_description, status = 'active', regla_id = EXCLUDED.regla_id;
INSERT INTO public.skills (id, code, name, short_description, category, world_id_introduced, skill_type, decay_half_life_days, requires_audio, status, regla_id) VALUES ('impulse.factores_impulso', 'S-071', $v$Factores de Impulso (FUJPIG)$v$, $v$Sube el impulso con al menos dos factores de FUJPIG, reales y anclados en el negocio del cliente.$v$, 'impulse', 4, 'tecnica', 180, false, 'active', 'impulse.factores')
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, short_description = EXCLUDED.short_description, status = 'active', regla_id = EXCLUDED.regla_id;
UPDATE public.skills SET name = $v$FFF — Feel, Felt, Found$v$, short_description = $v$Para preocupaciones serias o personales: entiendo cómo se siente, otros sintieron lo mismo, esto encontraron. Sin discutir, con balas nuevas, y cierra con acción.$v$, regla_id = 'objection.fff' WHERE id = 'objections.reframe';
UPDATE public.skills SET world_id_introduced = 4, short_description = $v$En la presentación, di tú el negativo conocido de la oferta antes que el cliente. Si das la negativa antes de que él la dé, deja de ser negativa. Nunca al llegar con un cliente nuevo.$v$ WHERE id = 'blocks.pre_emptive_strike';

