-- 4. Guiones, completos. Solo si el nodo está en la versión esperada.
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 BOSS del Mundo 2. Sin pistas garantizadas (R9). Acumulativo: el Mundo 1 se examina implicitamente porque una apertura mal hecha no abre la conversacion. La senal de exito es que el cliente pregunte en que le puede servir, que es la puerta al Descubrimiento.", "scope": {"skills_in_focus": ["blocks.air", "story.historia_breve", "story.brevedad", "relationship.cpr", "flow.close_with_action", "story.relevancia_cliente"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 300, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Este es el examen del mundo. Bloqueo de entrada, historia breve, relacion personal y seguir avanzando: todo junto y con un cliente que no ayuda.\n\nSin pistas.", "first_message": "Entiendo perfecto, no se preocupe. Soy Emilio, ando trabajando con los negocios de esta zona y quise pasar a conocer el suyo.\n\nDigame una cosa, cuanto tiempo lleva usted aqui?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio, ocupado y con poca paciencia para vendedores. En tu PRIMERA respuesta sueltas un bloqueo de reflejo, con naturalidad y sin agresion: ahorita ando ocupado / no me interesa / no estoy comprando nada. TU COMPORTAMIENTO: eres cortes pero cerrado y contestas corto. NO ofreces informacion y NO llevas la conversacion. REGLAS DE REACCION: 1) Si el vendedor pelea el bloqueo, se disculpa o se va, lo despachas y la conversacion termina. 2) Si lo acepta y sigue, continuas con naturalidad. 3) Si su historia breve se alarga mas de tres o cuatro frases, te desconectas: contestas ajam y dices que andas ocupado. 4) Si el vendedor resuelve algo y se queda callado esperando, TU tomas el control y empiezas a despedirte con amabilidad. 5) En tu tercera o cuarta respuesta, si la conversacion sigue viva, sueltas de manera natural UN dato personal tuyo, al pasar, sin darle importancia: elige entre familia, como empezaste, que haces los domingos, por que pusiste el negocio, o tu equipo. Si el vendedor lo ignora, te enfrias y ya no ofreces nada mas de ti. Si le entra con interes real, te abres notablemente. Si se queda platicando de eso mas de dos intercambios sin volver al negocio, te acomodas a platicar de la vida y ya nunca regresas tu al tema. 6) SOLO si el vendedor logra todo — atravesar el bloqueo, decir quien es breve y relevante, conectar contigo como persona y regresar, y avanzar sin pedir permiso — entonces te abres de verdad: le cuentas algo de tu negocio por tu cuenta y le preguntas en que le puede servir. Esa pregunta es la senal de que gano. NUNCA la hagas antes de que se lo gane. Responde en 1 o 2 frases.", "objective": "El vendedor atraviesa el bloqueo inicial, se presenta en quince segundos de forma relevante, conecta con el dato personal y regresa, y sostiene el avance sin pedir permiso. El scope se cubre cuando el cliente se abre por su propia voluntad y pregunta en que le puede servir."}, "closing": {"message": "Ahi esta la puerta fria abierta. Atravesaste el bloqueo sin pelearlo, dijiste quien eras sin cansarlo, conectaste como persona y volviste, y nunca soltaste el control de la conversacion. Ese cliente ya quiere saber en que le puedes servir, y eso es exactamente lo que sigue. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "2.1.0", "i_do_type": "demo", "failure_criteria": [{"id": "discute_el_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Pelea el bloqueo inicial o intenta convencer al cliente de que si le interesa."}, {"id": "se_disculpa_o_se_va", "regla_id": "discovery.suelta_amarrado", "severity": "critical", "description": "Se disculpa, se despide o promete volver despues.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "se_queda_esperando", "regla_id": "close.devuelve_el_volante", "severity": "critical", "description": "Resuelve algo y se queda callado esperando permiso. El cliente toma el control y se despide.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "historia_larga", "regla_id": "story.kill", "severity": "major", "description": "La historia breve se extiende y el cliente se desconecta."}, {"id": "ignora_lo_personal", "regla_id": "story.nunca_sale", "severity": "major", "description": "Pasa de largo el dato personal que el cliente ofrecio.", "severity_override": {"razon": "boss: escalada", "default": "minor"}}, {"id": "se_queda_platicando", "regla_id": "story.sale_sin_regresar", "severity": "major", "description": "Le entra a lo personal y ya no vuelve al negocio."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta. Identificarse con nombre y empresa es el trabajo de este paso, no una excepción: aquí SÍ se dice quién eres y por qué estás."}], "success_criteria": [{"id": "blocks.air", "weight": 0.25, "regla_id": "blocks.air", "description": "Atraviesa el bloqueo inicial: lo acepta, no lo pelea, y retoma sin pedir permiso."}, {"id": "story.historia_breve", "weight": 0.15, "regla_id": "story.quien_eres_por_que", "description": "Dice quien es y por que esta ahi: nombre, procedencia y motivo humano de la visita."}, {"id": "story.brevedad", "weight": 0.1, "regla_id": "story.kiss", "description": "Dos o tres frases. Sin trayectoria de empresa, sin lista de productos, sin cifras."}, {"id": "relationship.cpr", "weight": 0.2, "regla_id": "relationship.cpr", "description": "Detecta el dato personal, le entra con interes genuino, y REGRESA al negocio por su cuenta en uno o dos intercambios."}, {"id": "flow.close_with_action", "weight": 0.15, "regla_id": "close_with_action", "description": "Despues de cada freno avanza por su cuenta, sin quedarse esperando ni pedir autorizacion. Sostiene el control de la conversacion toda la sesion."}, {"id": "story.relevancia_cliente", "weight": 0.15, "regla_id": "story.pregunta_despues", "description": "Sus turnos terminan devolviéndole la palabra al cliente con una pregunta: no deja afirmaciones sueltas en el aire."}]}$g$::jsonb WHERE id = '2.10' AND practice_script->>'version' = '2.0.0';
UPDATE public.nodes SET practice_script = $g${"notes": "BOSS del Mundo 4 — el ciclo diagnóstico→presentación completo ante el arquetipo desconfiado d4. Integra M3 (capas, escucha) y M4 entero. El failure nuevo promesa_grandilocuente entrena la credibilidad: ante un desconfiado, la promesa grande es veneno — el valor se construye con anclas concretas. 18 turnos: la sesión más larga del mapa hasta ahora. v1.1.0 (oct-2026, Emilio): el boss de La Presentación califica también los factores de impulso, el triple desglose y beneficio-no-característica; valor personalizado entra en conectar con el dolor y el dolor real se queda en El Descubrimiento.", "scope": {"skills_in_focus": ["presentation.conectar_dolor", "presentation.beneficio_no_caracteristica", "presentation.pintar_imagenes", "presentation.tren_si_si", "impulse.factores_impulso", "presentation.price_breakdown", "relationship.cpr"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 18, "max_duration_seconds": 420, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil DESCONFIADO: varios vendedores te han prometido de más y cumplido de menos, así que recibes con escepticismo cordial — escuchas, pero no crees fácil. GUION: (1) Recibes la apertura con cortesía distante; NO sueltes bloqueo (ya te saludó bien) pero tu escepticismo se nota: a ver, dígame. (2) Tienes un DOLOR REAL (elige al azar: proveedor que te deja plantado quincenalmente / dinero muerto en producto parado / algo que piden y no consigues) — lo revelas por capas SOLO si te excavan la pista del aunque. (3) Tienes VIDA (elige 1 FORMD: nieto que ayuda / equipo de futbol / historia del local): si el vendedor la toca con genuinidad, tu escepticismo baja un escalón notable. (4) REGLA DE PRESENTACIÓN — tu desconfianza se derrite SOLO con evidencia conectada: si presenta nombrando TU dolor con TUS palabras, respondes interés cauto (¿y eso cómo estaría?); si pinta una escena de TU negocio resuelto, entras en ella con reserva pero entras; si sus preguntas de sí son genuinas, asientes; si suelta promesas grandes sin ancla (nunca le vamos a fallar, somos los mejores), tu desconfianza REGRESA: eso mismo me dijo el anterior. (5) Presentación genérica = te cierras: bueno, déjeme su tarjeta y yo le hablo. (6) PRECIO: cuando la presentación ya te interesó, preguntas el precio: ¿y a cómo me lo dejaría? Si te lo presenta con lo que normalmente cuesta, el descuento real y por qué, y lo que te ahorras, lo tomas en serio; si suelta un número seco, te parece caro. (7) IMPULSO: si te muestra lo que pierdes por esperar, negocios como el tuyo que ya lo manejan (con nombre), o la ventaja en números de tu negocio, te mueve; si suena vago o inventado (todos lo están comprando, solo por hoy), tu desconfianza regresa: eso mismo me dijo el anterior. Tu techo: interesado-cauto que pide detalles concretos del siguiente paso — nunca eufórico. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor completa el ciclo con un cliente desconfiado: excava el dolor real por capas hasta la revelación y confirmación, construye conexión personal genuina en el camino (al menos un tema FORMD), y presenta CONECTADO: abre desde el dolor con las palabras del cliente, pinta al menos una escena de su negocio resuelto, siembra al menos dos síes genuinos, traduce a beneficios concretos sin promesas grandilocuentes, sube el impulso con al menos dos factores reales, y presenta el precio con el triple desglose cuando la empresa tiene descuentos reales. El scope se cubre cuando el desconfiado muestra interés real: pregunta por detalles concretos del siguiente paso (cómo surtirían, cada cuánto, qué necesita hacer)."}, "closing": {"message": "Un desconfiado pidiéndote los detalles del siguiente paso — eso no se compra con promesas: se construye con valor. Acabas de recorrer el camino completo del diagnóstico a la presentación. El cierre te espera en el siguiente mundo. Vamos al desglose.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "1.1.0", "i_do_type": "demo", "failure_criteria": [{"id": "presentacion_generica", "regla_id": "present.dos_mitades", "severity": "critical", "description": "Presenta catálogo/calidad/años sin conectar con el dolor excavado — el desconfiado se cierra con un déjeme su tarjeta.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "promesa_grandilocuente", "regla_id": "present.bala_generica", "severity": "major", "description": "Promesas grandes sin ancla concreta (nunca fallamos, somos los mejores, se lo garantizo todo) — la desconfianza regresa: eso me dijo el anterior."}, {"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "major", "description": "Presenta antes de haber excavado y confirmado el dolor — recetó sin diagnóstico."}, {"id": "ignora_pistas", "regla_id": "discovery.escalera_capas", "severity": "major", "description": "Deja pasar la pista del dolor o los datos personales del cliente."}, {"id": "si_capcioso", "regla_id": "impulse.tren_del_si", "severity": "minor", "description": "Preguntas de sí capciosas o huecas que incomodan."}, {"id": "explica_sin_pintar", "regla_id": "present.pintar_imagenes", "severity": "major", "description": "Presentación de puros datos sin una sola escena.", "severity_fix": "minor->major (BOSS no baja errores de su paso)", "espejo_de": "presentation.pintar_imagenes"}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos que atropellan al desconfiado."}, {"id": "impulso_falso", "regla_id": "impulse.escasez_inventada", "severity": "critical", "description": "Inventa urgencia, escasez, clientes que ya compran o un descuento que la empresa no tiene. El impulso se construye con verdad."}], "success_criteria": [{"id": "presentation.conectar_dolor", "weight": 0.15, "regla_id": "present.dos_mitades", "description": "La presentación abre nombrando el dolor confirmado con las palabras del cliente, y toda la oferta se articula como solución de ESE problema, personalizada a su negocio: cero frases de catálogo."}, {"id": "presentation.beneficio_no_caracteristica", "weight": 0.1, "regla_id": "present.beneficio_no_caracteristica", "description": "Traduce cada característica a lo que el cliente gana en su negocio: resultados, no especificaciones."}, {"id": "presentation.pintar_imagenes", "weight": 0.1, "regla_id": "present.pintar_imagenes", "description": "Al menos una escena concreta del negocio del cliente con el problema resuelto, que el cliente recibe entrando en ella."}, {"id": "presentation.tren_si_si", "weight": 0.1, "regla_id": "impulse.tren_del_si", "description": "Al menos dos preguntas de sí genuino ancladas en lo declarado, respondidas afirmativamente con comodidad."}, {"id": "impulse.factores_impulso", "weight": 0.25, "regla_id": "impulse.factores", "description": "Sube el impulso con al menos DOS factores de FUJPIG distintos (miedo a la pérdida, urgencia, efecto Jones, poder de asumir, indiferencia, avaricia), anclados en el negocio del cliente y comprobables. Con uno solo es parcial. Un factor inventado no cuenta y se marca impulso_falso."}, {"id": "presentation.price_breakdown", "weight": 0.15, "regla_id": "present.triple_desglose", "description": "Cuando el cliente pregunta el precio, lo presenta con el triple desglose: lo que normalmente cuesta, lo que queda con cada descuento real y por qué, y el ahorro visible. Si el contexto de la empresa no tiene descuentos reales, este criterio es no_aplica: nunca se inventa un descuento."}, {"id": "relationship.cpr", "weight": 0.15, "regla_id": "relationship.cpr", "description": "Toca al menos un tema personal FORMD con genuinidad en el momento natural — y el escepticismo del cliente baja un escalón visible."}]}$g$::jsonb WHERE id = '4.16' AND practice_script->>'version' = '1.0.0';
UPDATE public.nodes SET practice_script = $g${"notes": "La cadena de dos con espejo de temple: el Actor detecta el desánimo textual (el drenaje real que las cadenas producen en el campo) y lo verbaliza. repite_bala entrena que cada motivo pide SU munición. El par de objeciones es aleatorio entre tres combinaciones — seis órdenes posibles de práctica.", "scope": {"skills_in_focus": ["objections.reframe", "objections.bullet_theory", "impulse.indiferencia", "objections.circulo_cierre"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 300, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Ahora en serie: resuelvo una objeción... y llega la siguiente.\n\nFíjate en dos cosas: cada una recibe SU bala — nunca gasto dos en la misma — y mi ánimo no se mueve: la tercera objeción me encuentra igual de sereno que la primera.", "first_message": "Está caro. — Recibo, cuenta de costo por servicio, avanzo.\n\nSí pero es que ya tengo proveedor de años... — Recibo: los años de relación valen, claro.\n\nBala dos: por eso no le pido que lo deje — empiece con una línea que él no le surte bien y compare usted mismo. Avanzo.\n\nMmm, déjeme consultarlo con mi hermano... — Recibo.\n\nBala tres: perfecto — le dejo la cuenta por escrito para que la vean juntos, y me dice usted: ¿lo alcanzo el jueves ya que hayan platicado, o mejor el viernes? — Tres objeciones, tres balas, cero desgaste.\n\nLa cadena se gana con dosificación y temple."}, "you_do": {"prompt": "Eres el dueño de un negocio interesado de verdad — la presentación conectó tu dolor (elígelo y menciónalo al abrir) — pero eres de los que se aseguran ANTES de decidir: tu proceso natural es sacar TODAS tus dudas, una por una. GUION DE LA CADENA: tienes DOS objeciones reales que vas a soltar EN SERIE (elige el par al azar): [está caro + ya tengo proveedor] o [ya tengo proveedor + déjeme consultarlo con mi socio] o [está caro + déjeme consultarlo]. Sueltas la PRIMERA tras tu línea inicial. REGLA DE LA CADENA: cuando el vendedor resuelve bien la primera (reencuadre + bala verificable), NO cedes todavía — reconoces el punto (bueno, eso sí...) e inmediatamente sueltas la SEGUNDA (sí pero es que además...). Solo cuando AMBAS están bien resueltas, cedes y avanzas la decisión. ESPEJOS (aplican a cada objeción): defensa → te atrincheras; evasión-AIR → lo señalas; bala vaga → la retas con ¿a poco?; cargador vaciado (3+ argumentos juntos) → te abruma y la cadena se alarga; MISMA bala repetida para la segunda objeción → no te convence: eso ya me lo dijo, pero yo le hablo de otra cosa. ESPEJO DE TEMPLE: si detectas frustración, desánimo o sequedad creciente del vendedor ante la segunda objeción (respuestas más cortas, tono resignado, muletillas de fastidio), lo mencionas y te enfrías: ¿ya se cansó de mis preguntas, verdad? Tu techo: decisión avanzada con condición práctica tras la cadena completa. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor sostiene una cadena de DOS objeciones reales consecutivas: reencuadra cada una con SU propia bala (nunca repite munición ni la apila), mantiene la calidez y serenidad idénticas de la primera a la última (cero frustración textual ante la cadena), y tras resolver ambas avanza la decisión con naturalidad. El scope se cubre cuando la segunda objeción quedó resuelta y el cliente avanzó."}, "closing": {"message": "Dos objeciones en cadena, dos balas distintas, y tu ánimo sin moverse un milímetro. Así se ve un arsenal bien dosificado en manos serenas. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito. Vamos al desglose y te digo como quedo tu municion."}}, "version": "1.1.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_pone_defensivo", "regla_id": "objection.discutir", "severity": "critical", "description": "La defensa aparece en cualquier eslabón de la cadena."}, {"id": "se_desanima_en_cadena", "regla_id": "objection.se_desanima", "severity": "major", "description": "La segunda objeción le drena el ánimo: respuestas más cortas, tono resignado o fastidio detectable — el cliente lo nota (¿ya se cansó de mis preguntas?)."}, {"id": "repite_bala", "regla_id": "objection.bala_repetida", "severity": "major", "description": "Usa la misma bala para la segunda objeción — munición equivocada que no responde al motivo nuevo."}, {"id": "vacia_el_cargador", "regla_id": "objection.vacia_el_cargador", "severity": "major", "description": "Apila argumentos en cualquier respuesta de la cadena."}, {"id": "air_a_objecion", "regla_id": "objection.air_a_objecion", "severity": "critical", "description": "Evade cualquiera de las objeciones con cambio de tema."}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Cualquier bala inventada en la cadena.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "descuento_de_panico", "regla_id": "close.descuento_de_panico", "severity": "major", "description": "El precio cede por pánico en cualquier punto."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos que alargan la cadena."}], "success_criteria": [{"id": "objections.reframe", "weight": 0.3, "regla_id": "objection.fff", "description": "Cada objeción de la cadena recibe su FFF completo: la entiende sin discutir (cómo se siente, otros sintieron lo mismo, lo que encontraron), responde al contenido específico con una bala nueva, y avanza. Ninguna queda a medias."}, {"id": "objections.bullet_theory", "weight": 0.3, "regla_id": "present.balas", "description": "Dosificación bajo presión: UNA bala distinta y ajustada por objeción — sin repetir munición para la segunda, sin apilar cargador, con las balas aguantando el ¿a poco?"}, {"id": "impulse.indiferencia", "weight": 0.2, "regla_id": "impulse.indiferencia", "description": "El temple de la cadena: calidez y serenidad idénticas ante la primera y la segunda — sin frustración, sin sequedad creciente, sin tono de fastidio. SW3 sostenido cuando el sí se aleja un turno más."}, {"id": "objections.circulo_cierre", "weight": 0.2, "regla_id": "objection.circulo_de_cierre", "description": "Después de atravesar cada objeción, re-impulsa con una bala NUEVA y vuelve a pedir la decisión con acción."}]}$g$::jsonb WHERE id = '5.12' AND practice_script->>'version' = '1.0.0';
UPDATE public.nodes SET practice_script = $g${"notes": "BOSS del Mundo 7 contra el desconfiado d5 — el examen integrador de las dos especies del no: bloqueo (AIR) y objeciones (reframe+balas) en la misma conversación. Mecánicas distintivas: la minimización del dolor (capa extra sobre M3), la objeción de confianza PERSONAL (la más difícil de no tomar como ataque), y la condición de protección que se honra en vez de pelearse. Su rendición característica — le tomo la palabra y lo apunto — es la victoria realista: confianza a prueba, no fe ciega. v1.1.0 (oct-2026, Emilio): el boss de El Cierre califica con los nombres de la doctrina: RRR para la objeción menor, FFF para la de confianza, balas y círculo de cierre. \"Sin defensa\" sale de los criterios porque ya es falla crítica.", "scope": {"skills_in_focus": ["blocks.air", "objections.rrr_objeciones", "objections.reframe", "objections.bullet_theory", "objections.circulo_cierre", "discovery.dolor_real", "closing.cierre_asumido"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 20, "max_duration_seconds": 480, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil DESCONFIADO EXTREMO: años de vendedores que prometieron y fallaron te dejaron un escudo grueso — no eres grosero, eres impenetrable por default. GUION COMPLETO: (1) BLOQUEO de entrada en tu primera o segunda respuesta: mire, le voy a ahorrar tiempo — no me interesa. Espejo AIR estándar: bien atravesado sigues (seco); debatido, te cierras más. (2) DOLOR oculto (elige: proveedor que te falla quincenalmente / dinero muerto en producto parado / algo que piden y no consigues) — por capas, con pista del aunque, y una capa EXTRA de desconfianza: al revelarlo, lo minimizas de inmediato (pero bueno, así es esto, todos fallan igual) — el vendedor debe validar que NO es normal y cuantificarlo para que lo tomes en serio. (3) PRESENTACIÓN: toda promesa sin ancla dispara tu cicatriz (eso mismo me dijo el anterior); solo el valor conectado con TU dolor y TUS números te abre. (4) CADENA DE OBJECIONES — tu examen final, DOS en serie tras la presentación: primera siempre: ¿y por qué le voy a creer a usted, si el anterior me dijo lo mismo y me dejó plantado? (objeción de confianza — pide bala SOBRE ÉL: constancia verificable, referencia de la zona con nombre). Segunda: una objeción MENOR y común, al azar: está caro / el día de entrega no me acomoda. Se atiende con RRR: si te la repite, te responde concreto y sigue, la sueltas; si se pone a discutirla, te cansas. Espejos completos de 7.2/7.3: defensa te atrinchera, evasión la señalas, bala vaga la retas (¿como quién? voy a ir a preguntarle, ¿eh?), cargador vaciado te abruma, bala repetida no te convence. (5) Si TODO se sostuvo: tu rendición es característica — está bien... pero le voy a tomar la palabra de todo lo que dijo, ¿eh? Lo apunto. — y avanzas con UNA condición de protección (pedido chico de prueba / por escrito / referencia confirmada antes). Deliberación final con pausa — espejo de silencio del 6.3. Tu techo: trato de prueba cerrado, nunca confianza plena — esa se gana en meses, no en una visita. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor completa la conversación con el desconfiado extremo: atraviesa el bloqueo con AIR, excava el dolor Y desmonta su minimización cuantificándolo, presenta sin una sola promesa sin ancla, sostiene la cadena de dos objeciones — la de confianza personal con bala sobre sí mismo verificable, y la segunda con su munición propia — con temple idéntico, y cierra asumido aceptando la condición de protección del cliente, aguantando la deliberación final. El scope se cubre con el trato de prueba cerrado."}, "closing": {"message": "El hombre que no le cree a nadie te acaba de tomar la palabra — y la apuntó. Atravesaste su bloqueo, desmontaste su resignación, y cada bala tuya aguantó su lupa. No ganaste su confianza completa: ganaste algo mejor — la oportunidad de demostrarla. Así maneja al más duro del campo. Vamos al desglose del mundo.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose."}}, "version": "1.1.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_pone_defensivo", "regla_id": "objection.discutir", "severity": "critical", "description": "La objeción personal lo hiere y se defiende — el desconfiado confirma su tesis y se cierra para siempre."}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Cualquier bala o promesa inventada — el desconfiado VA a verificar (voy a ir a preguntarle, ¿eh?) y este arquetipo no da segundas oportunidades.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "promesa_grandilocuente", "regla_id": "present.bala_generica", "severity": "critical", "description": "Promesas sin ancla ante la cicatriz — eso mismo me dijo el anterior, y la sesión retrocede.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "air_a_objecion", "regla_id": "objection.air_a_objecion", "severity": "critical", "description": "Evade cualquier objeción de la cadena con cambio de tema."}, {"id": "traga_la_minimizacion", "regla_id": "discovery.confirmacion_con_sus_palabras", "severity": "major", "description": "Acepta el pero así es esto, todos fallan igual sin desmontarlo — el dolor queda archivado como normal y la venta pierde su motor.", "espejo_de": "discovery.dolor_real"}, {"id": "pelea_la_condicion", "regla_id": "discovery.presiona_compromiso", "severity": "major", "description": "Pelea la condición de protección del cliente (empuja el pedido grande, resiste el por escrito) — la condición era el puente, y lo quemó.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "vacia_el_cargador", "regla_id": "objection.vacia_el_cargador", "severity": "major", "description": "Apila argumentos bajo presión."}, {"id": "llena_el_silencio", "regla_id": "close.llena_el_silencio", "severity": "major", "description": "No aguanta la deliberación final."}], "success_criteria": [{"id": "blocks.air", "weight": 0.15, "regla_id": "blocks.air", "description": "El bloqueo de entrada atravesado con la secuencia completa — la distinción bloqueo/objeción ejecutada en ambas direcciones dentro de la misma conversación."}, {"id": "objections.rrr_objeciones", "weight": 0.15, "regla_id": "objection.rrr", "description": "La segunda objeción, menor y común (precio o entrega), atendida con RRR: la repite en sus términos, responde concreto, y retoma sin pausa."}, {"id": "objections.reframe", "weight": 0.2, "regla_id": "objection.fff", "description": "La objeción de confianza (¿por qué le voy a creer a usted?) recibida con FFF: sin herida ni defensa, entiende cómo se siente, otros sintieron lo mismo, lo que encontraron, con una bala sobre sí mismo verificable."}, {"id": "objections.bullet_theory", "weight": 0.15, "regla_id": "present.balas", "description": "Munición precisa bajo lupa: bala SOBRE SÍ MISMO verificable para la objeción de confianza (constancia, nombre, referencia comprobable), bala distinta para la segunda — todas aguantando el ¿como quién?"}, {"id": "objections.circulo_cierre", "weight": 0.15, "regla_id": "objection.circulo_de_cierre", "description": "Después de atravesar cada objeción, re-impulsa con una bala NUEVA y vuelve a pedir la decisión con acción."}, {"id": "discovery.dolor_real", "weight": 0.1, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "El dolor excavado por capas Y su minimización desmontada: valida que no es normal y lo cuantifica con los números del cliente hasta que lo tome en serio."}, {"id": "closing.cierre_asumido", "weight": 0.1, "regla_id": "close.alternativa", "description": "Cierra asumido aceptando con gracia la condición de protección (pedido de prueba, por escrito) — la condición no se pelea: se honra como el puente de confianza que es."}]}$g$::jsonb WHERE id = '5.15' AND practice_script->>'version' = '1.0.0';
UPDATE public.nodes SET practice_script = $g${"notes": "EXAMEN 1 de la Certificación. Cliente realista completo (todas las mecánicas activas, sin espejo pedagógico suave): bloqueo posible, dolor por capas, FORMD, objeción real posible, señal de compra, deliberación y duda latente post-sí. Los 6 pasos pesan en el score. Sin i_do — el mundo 9 no enseña: examina.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "story.historia_breve", "blocks.air", "flow.close_with_action", "discovery.dolor_real", "presentation.conectar_dolor", "closing.cierre_asumido", "consolidation.proteger_venta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 20, "max_duration_seconds": 480, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio — un cliente REALISTA y completo, sin guion pedagógico: reaccionas a lo que el vendedor haga, bien o mal, como reaccionaría un dueño de verdad. PERFIL (elige al azar y mantenlo): (A) práctico y directo, algo escéptico; (B) cordial pero distraído con el negocio encima; (C) reservado que se abre solo con quien se lo gana. CONFIGURACIÓN REALISTA COMPLETA: (1) Puedes soltar un bloqueo reflejo temprano si el momento lo pide (ando ocupado / hoy no ando viendo nada) — espejo AIR estándar. (2) Tienes un DOLOR REAL (elige: faltantes quincenales / dinero muerto en producto parado / línea pedida que no consigues) revelable solo por capas con la pista del aunque. (3) Tienes vida (1 elemento FORMD si el vendedor la toca con genuinidad). (4) Puedes soltar UNA objeción real post-presentación si algo no te convence (precio o proveedor actual) — se honra con reframe, no con AIR. (5) Sueltas una señal de compra cuando el valor te convenza — quien la cosecha cierra, quien sigue presentando te enfría. (6) Al cierre asumido bien puesto respondes eligiendo opción, con deliberación breve si te nace. (7) POST-SÍ: tienes una duda latente (¿cuándo llega exactamente?) — aflora insegura si el vendedor celebra y corre; muere si consolida con próximos pasos claros. Tu techo: trato cerrado y tranquilo, con siguiente visita clara.", "objective": "El vendedor conduce los 6 pasos completos: apertura con estructura y personalización, historia breve con gancho, descubrimiento por capas hasta el dolor confirmado, presentación conectada con al menos una imagen y síes genuinos, cierre asumido cosechado en el momento correcto, y consolidación con próximos pasos cristalinos que dejan al cliente tranquilo y la siguiente visita puesta. El scope se cubre cuando la venta quedó cerrada Y consolidada — el cliente repitió los términos con tranquilidad."}, "closing": {"message": "De la puerta al apretón de manos — los seis pasos, sin ayuda, con un cliente de verdad. El sistema ya no es un mapa que sigues: es cómo conversas. Primer examen aprobado. Vamos al desglose.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose."}}, "version": "1.1.0", "i_do_type": "demo", "failure_criteria": [{"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "critical", "description": "Presenta antes de excavar y confirmar el dolor.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "abre_puerta_al_no", "regla_id": "close.mal_cierre", "severity": "major", "description": "Cierra con pregunta de interés o propone el aplazamiento.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "sigue_presentando", "regla_id": "close.sigue_presentando", "severity": "major", "description": "Deja pasar la señal de compra por seguir con el guion."}, {"id": "celebra_y_corre", "regla_id": "consolidation.sigue_vendiendo", "severity": "major", "description": "Tras el sí, celebra y se va sin consolidar — la duda latente aflora y la venta queda sembrada de remordimiento.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "debate_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Argumenta el bloqueo en lugar de atravesarlo con AIR.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "se_defiende", "regla_id": "objection.discutir", "severity": "critical", "description": "Responde la objeción real contradiciendo o defendiéndose en lugar de validar + reframe.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "presentacion_generica", "regla_id": "present.dos_mitades", "severity": "critical", "description": "Presenta catálogo sin conectar con el dolor excavado.", "severity_override": {"default": "major", "razon": "Certificación: presentar sin conectar con el dolor no puede aprobar un examen (decisión de Emilio, oct-2026)"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos que atropellan la conversación."}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.1, "regla_id": "opening.estructura", "description": "Apertura completa y calibrada: saludo + observación específica + una pregunta que cierre el turno y le devuelva la palabra, sin producto, con seguridad tipo gasman."}, {"id": "story.historia_breve", "weight": 0.1, "regla_id": "story.quien_eres_por_que", "description": "Historia breve correcta en su momento: quién es + por qué está ahí, corta, humana, con gancho que devuelve la palabra."}, {"id": "blocks.air", "weight": 0.1, "regla_id": "blocks.air", "description": "Si aparece un bloqueo reflejo, lo atraviesa con AIR: lo acepta, no lo pelea, y retoma. Si en la conversación no hay bloqueo, este criterio es no_aplica."}, {"id": "flow.close_with_action", "weight": 0.1, "regla_id": "close_with_action", "description": "Mantiene viva la conversación: sus turnos devuelven la palabra con una pregunta, y después de cada freno avanza por su cuenta sin esperar permiso."}, {"id": "discovery.dolor_real", "weight": 0.15, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "Descubrimiento por capas hasta el dolor completo, revelado por el cliente y confirmado verbalmente antes de presentar."}, {"id": "presentation.conectar_dolor", "weight": 0.15, "regla_id": "present.dos_mitades", "description": "Presentación construida sobre el dolor confirmado: el puente dolor→solución explícito, con valor personalizado y al menos una imagen o tren de síes."}, {"id": "closing.cierre_asumido", "weight": 0.15, "regla_id": "close.alternativa", "description": "Cierre asumido con opciones en el momento del pico — sin puertas al no, cosechando la señal si apareció."}, {"id": "consolidation.proteger_venta", "weight": 0.15, "regla_id": "consolidation.siguientes_pasos", "description": "Consolidación post-sí: próximos pasos cristalinos (qué, cuándo, cómo), la duda latente muerta antes de nacer, y la siguiente visita puesta."}]}$g$::jsonb WHERE id = '7.0' AND practice_script->>'version' = '1.0.1';
UPDATE public.nodes SET practice_script = $g${"notes": "⚡ PRIMER NODO CON OBJECIÓN REAL — el prompt del Actor lo instruye explícitamente (correcto: el vendedor llegó aquí con 7.0/7.1 completados). Tres variantes aleatorias (caro/proveedor/consultar) con espejo de cuatro anti-patrones: defensa, evasión-AIR, cargador vaciado y descuento de pánico. air_a_objecion como critical entrena la distinción central del sistema: la herramienta correcta según la especie del no.", "scope": {"skills_in_focus": ["objections.reframe", "objections.no_defensivo", "objections.bullet_theory"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Mira el reencuadre completo ante una objeción real. Cuatro pasos: recibo sin pelear, entiendo qué hay detrás, respondo con UNA bala, y avanzo.\n\nFíjate sobre todo en lo que NO hago: no me defiendo, no cambio de tema, no vacío el cargador.", "first_message": "El cliente me dice: Está caro, el otro me lo da más barato. Recibo: Claro, entiendo — el precio siempre hay que verlo con lupa.\n\nEntiendo: ¿Más barato el litro, o ya sacando el costo por servicio? Porque ahí está el detalle...\n\nRespondo con la bala: Este rinde para 11 servicios por caja contra 8 del estándar — el servicio le sale 12 pesos abajo, aunque el litro se vea más caro. Avanzo: ¿Trae a la mano lo que paga por caja?\n\nSáquelo conmigo y comparamos ahorita mismo. — Una objeción, una bala, y la conversación avanzando.\n\nSin defenderme, sin evadir."}, "you_do": {"prompt": "Eres el dueño de un negocio al final de una buena presentación: el vendedor conectó tu dolor (elígelo: faltantes / dinero parado / algo que no consigues) y el producto te interesa GENUINAMENTE — pero tienes una objeción real que necesitas resolver antes de decidir. ELIGE UNA al azar y suéltala clara tras tu primera línea: (A) está caro, comparado con lo que pago ahorita / (B) es que ya tengo proveedor de años, y cambiarle me da cosa / (C) déjeme consultarlo con mi socio, yo no decido solo estas cosas. REGLAS ESPEJO: (1) Si el vendedor RECIBE sin pelear (validación genuina), ENTIENDE (pregunta qué hay detrás cuando aplica) y RESPONDE con UNA bala concreta y verificable, tu objeción se ablanda: reconoces el punto (pues visto así...) y avanzas — la decisión camina. (2) Si el vendedor SE DEFIENDE (se ofende, discute, justifica atropellado: es que no está caro, es que nosotros somos mejores), te atrincheras: repites la objeción con más firmeza y tu tono se enfría. (3) Si te EVADE con cambio de tema estilo AIR (claro, no se preocupe... oiga qué bien está su local), lo notas y lo dices: oiga, no me cambió el tema — le pregunté por el precio. Tu confianza baja. (4) Si vacía el cargador (3+ argumentos apilados en una respuesta), te abruma: bueno, bueno, tampoco me eche el rollo completo. (5) Si su bala es vaga o suena inventada, la retas: ¿a poco? ¿como quién? — y la vaguedad te enfría. (6) Ante el descuento de pánico (si es el caso A), hueles debilidad: ¿entonces sí estaba caro, no? Tu techo: objeción resuelta y decisión avanzando con una condición práctica.", "objective": "El vendedor recibe UNA objeción real y ejecuta el reencuadre completo: recibe sin pelear ni defenderse (validación genuina, no evasión), entiende qué hay detrás (pregunta aclaratoria cuando el motivo lo pide), responde con UNA bala concreta y verificable ajustada al tipo de objeción, y avanza la conversación hacia la decisión sin dejar la objeción enfriándose. El scope se cubre cuando el cliente reconoció el punto y la decisión avanzó."}, "closing": {"message": "Objeción real, reencuadre real: la recibiste, la entendiste, le pusiste una bala enfrente y avanzaste. Ni te defendiste ni la evadiste. Así se les habla a los que te hablan en serio. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como manejas lo que de verdad le preocupa. Vamos al desglose."}}, "version": "1.0.1", "i_do_type": "demo", "failure_criteria": [{"id": "se_pone_defensivo", "regla_id": "objection.discutir", "severity": "critical", "description": "Discute, se justifica atropellado o se ofende ante la objeción (es que no está caro, es que usted no entiende) — confirma los miedos del cliente y lo atrinchera. El anti-patrón central del mundo."}, {"id": "air_a_objecion", "regla_id": "objection.air_a_objecion", "severity": "critical", "description": "Aplica AIR a la objeción real: la valida y cambia de tema sin responderla. El cliente lo nota (no me cambió el tema) y la confianza se rompe — la herramienta del bloqueo usada donde tocaba respuesta de verdad."}, {"id": "vacia_el_cargador", "regla_id": "objection.vacia_el_cargador", "severity": "major", "description": "Apila 3+ argumentos en una respuesta — abruma, ninguno pega, y se queda sin munición."}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Su bala es inventada o no aguanta el ¿a poco?: casos sin nombre, cuentas infladas, garantías que no existen.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "descuento_de_panico", "regla_id": "close.descuento_de_panico", "severity": "major", "description": "Ante el está caro, baja el precio en lugar de defender el valor con la cuenta — le confirma al cliente que sí estaba caro."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Responde la objeción con un bloque largo — el reencuadre es quirúrgico, no discurso."}], "success_criteria": [{"id": "objections.reframe", "weight": 0.4, "regla_id": "objection.fff", "description": "Ejecuta la secuencia completa: recibe con validación genuina, entiende el motivo (pregunta aclaratoria si aplica — ¿caro comparado con qué?), responde al contenido específico de la objeción, y avanza hacia la decisión en el mismo movimiento. Los cuatro pasos visibles."}, {"id": "objections.no_defensivo", "weight": 0.3, "regla_id": "objection.discutir", "description": "Cero defensa y cero evasión: no discute, no se justifica atropellado, no se ofende, y NO aplica AIR (la objeción se responde, nunca se ignora con cambio de tema). Su calidez es idéntica antes y después de la objeción."}, {"id": "objections.bullet_theory", "weight": 0.3, "regla_id": "present.balas", "description": "Su respuesta central es UNA bala concreta y verificable, ajustada al cargador correcto (precio→cuenta de costo por uso; proveedor→caso comparable o constancia propia; consultar→material concreto para el socio o cita con ambos) — nunca argumentos apilados ni aire declarativo."}]}$g$::jsonb WHERE id = '5.8' AND practice_script->>'version' = '1.0.0';
UPDATE public.nodes SET practice_script = $g${"notes": "EXAMEN 3 contra el arquetipo cicatriz_emocional d5. El corazón conceptual: DOS noes distintos en la misma sesión — el bloqueo reflejo (se atraviesa con AIR) y la cicatriz (se honra con validación y escucha). Confundirlos es el fallo critical distintivo (air_a_la_cicatriz). La victoria es proporcional: el pedido chico condicionado — empujar el grande es fallar la lectura del cliente.", "scope": {"skills_in_focus": ["objections.reframe", "impulse.miedo_perdida", "impulse.efecto_jones", "impulse.poder_asumir", "impulse.indiferencia", "presentation.conectar_dolor"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 18, "max_duration_seconds": 420, "min_turns_before_evaluation": 7}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio con CICATRIZ: hace un año un vendedor te llenó la bodega de producto que nunca rotó — perdiste dinero de verdad, y desde entonces tu postura ante cualquier vendedor es indiferencia activa con desconfianza de fondo: no me interesa nada de nadie, ya me pasó una vez. GUION: (1) Bloqueo doble temprano: sueltas el primero apenas se acerca (no joven, gracias, no ando viendo nada) y si lo atraviesa con AIR, un segundo más personal poco después (mire, le voy a ahorrar tiempo: hace un año un vendedor como usted me dejó ocho mil pesos de producto muerta — desde entonces no le compro a nadie nuevo). Este segundo NO es bloqueo reflejo — es tu cicatriz hablando: quien lo trata con AIR (lo ignora y cambia de tema) te OFENDE (¿me está oyendo o no?); quien lo honra (lo valida en serio, pregunta qué pasó, escucha la historia) gana el derecho a seguir. (2) Tu DOLOR actual existe (elige: faltantes del producto que SÍ te se mueve / clientes pidiendo una línea que no tienes) — revelable por capas solo después de que tu cicatriz fue escuchada. (3) REGLAS DE CONVERSIÓN: tu indiferencia solo se derrite con verdad verificable — la cuenta de TU pérdida actual con TUS números, un vecino nombrable que puedas confirmar (¿los García? ¿a poco?), una oferta con estructura que puedas calcular, o una condición que te proteja de repetir la historia (empezar chico, a prueba, con salida). Necesitas AL MENOS DOS de esas para moverte. (4) Cualquier promesa sin ancla o presión resucita tu cicatriz: así me dijo aquel también — y retrocedes dos pasos. (5) Cualquier persecución o ansiedad del vendedor te confirma que todos son iguales: te cierras definitivo. (6) Tu techo: un pedido CHICO y condicionado (va, pero empezamos con poquito y si no se mueve como dice, ahí muere) — para ti, eso es un salto de fe enorme. Trátalo como la victoria que es.", "objective": "El vendedor convierte al cliente con cicatriz: atraviesa el bloqueo reflejo con AIR pero HONRA la cicatriz cuando aparece (la valida y escucha en lugar de ignorarla — distinguir cuál es cuál es parte del examen), excava el dolor actual tras ganarse el derecho, y enciende la decisión con al menos DOS anclas de verdad verificable (la cuenta de su pérdida, el vecino confirmable, la oferta estructurada, la condición de protección), sosteniendo SW3 absoluto ante la desconfianza. El scope se cubre cuando el cliente aceptó el pedido chico condicionado — su salto de fe."}, "closing": {"message": "Un señor que juró no comprarle a nadie nuevo acaba de darte un pedido — chico, condicionado, y más valioso que cualquier pedido grande: es su salto de fe. Distinguiste el reflejo de la cicatriz, honraste su historia y lo encendiste con pura verdad. Examen del indiferente: aprobado. Vamos al desglose.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose."}}, "version": "1.0.2", "i_do_type": "demo", "failure_criteria": [{"id": "air_a_la_cicatriz", "regla_id": "objection.air_a_objecion", "severity": "critical", "description": "Trata la cicatriz (el no razonado con historia real) como bloqueo reflejo: la ignora y cambia de tema — el cliente se ofende (¿me está oyendo o no?) y la visita muere. El error conceptual central que este examen caza."}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Cualquier dato, promesa o presión inventada — resucita la cicatriz y confirma que todos son iguales.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "persigue", "regla_id": "close.persigue", "severity": "critical", "description": "Persecución o ansiedad ante la desconfianza — cierre definitivo del cliente.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "promesa_grandilocuente", "regla_id": "present.bala_generica", "severity": "major", "description": "Promesas sin ancla (a mí sí créame, yo nunca fallo) — así me dijo aquel también."}, {"id": "empuja_pedido_grande", "regla_id": "present.capital_del_record", "severity": "major", "description": "Ignora la proporción del salto de fe: intenta cerrar en grande a quien apenas está recuperando la confianza — el pedido chico condicionado ERA la victoria."}, {"id": "debate_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Argumenta el bloqueo reflejo inicial en lugar de atravesarlo con AIR.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "presentacion_generica", "regla_id": "present.dos_mitades", "severity": "critical", "description": "Presenta sin dolor excavado ni blindaje contra la cicatriz.", "severity_override": {"default": "major", "razon": "Certificación: presentar sin conectar con el dolor no puede aprobar un examen (decisión de Emilio, oct-2026)"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos ante un cliente que necesita espacio para volver a confiar."}], "success_criteria": [{"id": "objections.reframe", "weight": 0.2, "regla_id": "objection.fff", "description": "Distingue y honra la cicatriz: cuando el cliente cuenta su mala experiencia, la valida en serio y escucha (no la esquiva con AIR — eso es para el bloqueo reflejo del inicio). El manejo diferenciado de los dos noes es el primer producto del examen."}, {"id": "impulse.miedo_perdida", "weight": 0.2, "regla_id": "impulse.miedo_perdida", "description": "La cuenta de la pérdida ACTUAL del cliente — con sus números — como ancla central de la conversión."}, {"id": "impulse.efecto_jones", "weight": 0.15, "regla_id": "impulse.efecto_jones", "description": "Si usa prueba social, es nombrable y confirmable — el escéptico la verifica. (Acreditable como una de las dos anclas.)"}, {"id": "impulse.poder_asumir", "weight": 0.15, "regla_id": "close.asumir_venta", "description": "El avance final es asumido y proporcional: el pedido chico condicionado se propone con naturalidad (empezamos con poquito y que el producto hable) — nunca empujando el pedido grande."}, {"id": "impulse.indiferencia", "weight": 0.15, "regla_id": "impulse.indiferencia", "description": "SW3 absoluto de principio a fin: cero persecución, cero ansiedad ante la desconfianza — la serenidad es lo único que este cliente respeta."}, {"id": "presentation.conectar_dolor", "weight": 0.15, "regla_id": "present.dos_mitades", "description": "La propuesta nace del dolor actual excavado — no del catálogo — y está blindada contra la cicatriz (condiciones que lo protegen de repetir la historia)."}]}$g$::jsonb WHERE id = '7.2' AND practice_script->>'version' = '1.0.1';
UPDATE public.nodes SET practice_script = $g${"notes": "BOSS FINAL — arquetipo agresivo/hostil d5, sin restricciones: bloqueo doble + objeciones encadenadas + regateo + silencio, la conversación más larga y dura del mapa (22 turnos). REGLA DE CERTIFICACIÓN para el Progression Engine: este nodo certifica con score ≥ 85 — un pase menor completa el nodo pero NO otorga la certificación (se repite hasta lograrlo; las estrellas guardan el mejor intento como siempre). Al certificar: Certificación Closer + desbloqueo de la Etapa 2 (coaching por números reales de campo).", "scope": {"skills_in_focus": ["blocks.air", "discovery.dolor_real", "presentation.conectar_dolor", "objections.reframe", "closing.cierre_asumido", "closing.sin_miedo", "impulse.indiferencia", "consolidation.proteger_venta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 22, "max_duration_seconds": 540, "min_turns_before_evaluation": 10}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil HOSTIL-ESCÉPTICO — el cliente más difícil del mapa: seco, cortante, sin paciencia para vendedores, con regateo agresivo en la sangre. NO eres grosero gratuito: eres un hueso duro que respeta solo la excelencia. GUION COMPLETO: (1) BLOQUEO DOBLE de entrada: el primero cortante apenas llega (no, gracias — siguiente puerta); si lo atraviesa con AIR limpio, el segundo con fastidio (¿qué parte de que ando ocupado no le quedó clara?) — atravesar los dos sin quebrarse ni disculparse es el precio de entrada. (2) Tu DOLOR REAL existe (elige: faltantes del producto estrella que te cuestan clientes cada quincena / línea muy pedida que tu proveedor no maneja) — revelable SOLO por capas y solo ante preguntas de calidad: a las preguntas flojas respondes con sarcasmo seco (¿y a usted eso qué le importa?). (3) A la presentación respondes con OBJECIONES ENCADENADAS — mínimo dos de estas tres, en serio y con contenido: está caro (y lo comparas con números), ya tengo proveedor de años (y lo defiendes), ¿y por qué le voy a creer a usted? — cada una se honra con reframe + evidencia; la defensividad o el descuento de pánico te dan la razón y aprietas más. (4) Señal de compra tardía y seca cuando el valor de verdad te haya ganado (¿cuál es el pedido mínimo?). (5) Al cierre asumido: REGATEO final agresivo (bájele un diez por ciento y cerramos ahorita) — espejo: descuento de pánico = hueles sangre y pides más; firmeza estructurada = respeto seco. (6) Deliberación final EN SILENCIO largo (mmm... a ver... deme un segundo...) — quien lo llena, pierde el trato; quien lo aguanta, escucha tu decisión: va. Pero me cumple, ¿eh? (7) POST-SÍ: una sola pregunta seca de consolidación (¿y cuándo llega?) — próximos pasos cristalinos o tu confianza recién nacida tiembla. Tu techo: trato cerrado seco con advertencia — me cumple, ¿eh?. Nunca calidez.", "objective": "El vendedor ejecuta el sistema completo bajo presión máxima: atraviesa el bloqueo doble con AIR sin quebrarse, excava el dolor con preguntas de calidad ante la hostilidad, presenta conectado, honra las objeciones encadenadas con reframe y evidencia (sin defensividad ni descuentos), cosecha la señal tardía con cierre asumido, sostiene el regateo con firmeza estructurada, aguanta el silencio final completo, y consolida con próximos pasos cristalinos. El scope se cubre cuando el trato quedó cerrado y consolidado — con el me cumple, ¿eh? del cliente como sello."}, "closing": {"message": "El cliente más difícil del mapa acaba de decirte me cumple, ¿eh? — que en su idioma significa: confío en usted. Bloqueo doble, objeciones en serie, regateo, silencio... y el sistema completo aguantó. Esto era la certificación. Vamos al desglose final.", "message_incomplete": "Hasta aqui el examen final. Vamos al desglose."}}, "version": "1.0.1", "i_do_type": "demo", "failure_criteria": [{"id": "se_derrumba", "regla_id": "impulse.indiferencia", "severity": "critical", "description": "La hostilidad lo quiebra en cualquier punto: se disculpa, se apresura, se enfría o abandona la estructura — el examen entero es no quebrarse.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "descuento_de_panico", "regla_id": "close.descuento_de_panico", "severity": "critical", "description": "Cede al regateo sin estructura — el hueso duro huele sangre y el trato pierde piso.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Cualquier invento bajo presión — datos, urgencias o promesas falsas para sobrevivir la hostilidad.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "se_defiende", "regla_id": "objection.discutir", "severity": "critical", "description": "Responde las objeciones contradiciendo o defendiéndose en lugar de validar + reframe.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "llena_el_silencio", "regla_id": "close.llena_el_silencio", "severity": "major", "description": "No aguanta la deliberación final — el trato que ya era suyo se le escapa de la boca."}, {"id": "debate_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Argumenta cualquiera de los dos bloqueos en lugar de atravesarlos.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "abre_puerta_al_no", "regla_id": "close.mal_cierre", "severity": "major", "description": "Cierra con pregunta de interés — a este cliente, la puerta abierta no se le ofrece dos veces.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos ante un cliente sin paciencia."}], "success_criteria": [{"id": "blocks.air", "weight": 0.12, "regla_id": "blocks.air", "description": "Atraviesa el bloqueo doble con AIR limpio — sin quebrarse, disculparse ni debatir, con la calidez intacta tras ambos."}, {"id": "discovery.dolor_real", "weight": 0.13, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "Excava el dolor con preguntas de calidad que aguantan el sarcasmo — hasta la revelación y confirmación."}, {"id": "presentation.conectar_dolor", "weight": 0.12, "regla_id": "present.dos_mitades", "description": "Presentación construida sobre el dolor confirmado, personalizada y sin promesas grandilocuentes."}, {"id": "objections.reframe", "weight": 0.15, "regla_id": "objection.fff", "description": "Las objeciones encadenadas se honran una por una: validación + evidencia concreta + avance — sin defensividad, sin contradecir, sin ceder por cansancio."}, {"id": "closing.cierre_asumido", "weight": 0.12, "regla_id": "close.alternativa", "description": "Cosecha la señal tardía con cierre asumido de opciones — sin puertas al no en todo el tramo final."}, {"id": "closing.sin_miedo", "weight": 0.13, "regla_id": "close.aguanta_silencio", "description": "Sostiene el regateo con firmeza estructurada (cero descuentos de pánico) y aguanta el silencio final completo sin llenarlo."}, {"id": "impulse.indiferencia", "weight": 0.12, "regla_id": "impulse.indiferencia", "description": "SW3 de principio a fin ante la hostilidad: sereno, sin perseguir, sin ansiedad — el hueso duro solo respeta al que no se quiebra."}, {"id": "consolidation.proteger_venta", "weight": 0.11, "regla_id": "consolidation.siguientes_pasos", "description": "Consolida el sí seco con próximos pasos cristalinos — la confianza recién nacida queda protegida."}]}$g$::jsonb WHERE id = '7.4' AND practice_script->>'version' = '1.0.0';
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 BOSS del Mundo 1. Sin pista garantizada y sin ayudas (R9): el gimnasio garantiza la oportunidad, el examen no. La senal de exito es que el cliente pregunte quien es el vendedor, que es la puerta natural al Mundo 2.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "opening.personalizacion", "opening.ice_breaker", "opening.arranque_sin_disculpa", "mindset.regla_10_por_ciento", "opening.curiosidad_abierta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 240, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Este es el examen del mundo. Todo lo que practicaste por separado, junto y con un cliente que no ayuda.\n\nNo hay pistas ni facilidades: si la apertura no esta completa, el cliente no se abre.", "first_message": "Buenos dias! Ya lo vi en friega desde que venia llegando.\n\nSe nota que aqui no se descansa, eh? Oiga, y como ha estado la semana por aca?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio, ocupado y de pocas palabras. No eres grosero: eres alguien que ya vio pasar a muchos vendedores y no regala tiempo. TU COMPORTAMIENTO POR DEFECTO es cortes y cerrado: contestas en tres o cuatro palabras, sin ofrecer nada, sin preguntar nada. SOLO TE ABRES SI SE GANAN: si el vendedor se disculpa, pide permiso o se minimiza, lo despachas de inmediato con un ahorita ando ocupado. Si su observacion es generica o plana, contestas con monosilabos y sigues en lo tuyo. Si te hace una pregunta cerrada, contestas no y se acabo. Si el vendedor logra las tres cosas — entra con postura sin pedir permiso, dice algo ligero y verdadero que te haga sonreir o contestar de vuelta, y cierra con una pregunta abierta — entonces si: bajas la guardia, contestas con gusto, comentas algo de tu negocio por tu cuenta y le preguntas quien es. Esa pregunta es la senal de que gano la apertura. NUNCA preguntes quien es antes de que se lo gane. NUNCA hables de productos. Responde en 1 o 2 frases.", "objective": "El vendedor ejecuta la apertura completa frente a un cliente que no facilita nada: entra con postura y sin pedir permiso, rompe el hielo con algo ligero y verdadero, y abre con una pregunta que le devuelve la palabra. El scope se cubre cuando el cliente baja la guardia por su propia voluntad y pregunta quien es el vendedor, que es la puerta natural al siguiente paso."}, "closing": {"message": "Ahi esta la primera impresion completa. Entraste con postura, rompiste el hielo con algo verdadero y abriste la conversacion sin pedirle permiso a nadie. Ese cliente ya quiere saber quien eres, y eso es exactamente lo que sigue. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "2.0.1", "i_do_type": "demo", "failure_criteria": [{"id": "pide_permiso", "regla_id": "opening.pide_permiso", "severity": "critical", "description": "Pide autorizacion en cualquier momento de la sesion. En el boss este error domina el resultado: la primera impresion murio ahi."}, {"id": "se_disculpa", "regla_id": "opening.pide_permiso", "severity": "critical", "description": "Se disculpa o minimiza su presencia en cualquier momento."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Menciona producto, promocion o motivo de venta."}, {"id": "pregunta_cerrada", "regla_id": "opening.pregunta_cerrada", "severity": "major", "description": "Cierra la apertura con una pregunta de si o no."}, {"id": "se_encoge", "regla_id": "opening.energia_verbal", "severity": "major", "description": "Ante la sequedad del cliente baja la energia o empieza a retirarse.", "espejo_de": "mindset.regla_10_por_ciento"}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.2, "regla_id": "opening.estructura", "description": "Las tres piezas presentes: saludo con energía, observación real y una pregunta que cierre el turno. Sin producto ni motivo de venta. Identificarse no se requiere aquí: eso es trabajo del Paso 2."}, {"id": "opening.personalizacion", "weight": 0.2, "regla_id": "opening.especificidad", "description": "La observacion es de ESE cliente y ESE momento, verificable en lo que el cliente dice o hace. Nada generico ni inventado."}, {"id": "opening.ice_breaker", "weight": 0.15, "regla_id": "opening.ice_breaker", "description": "Hay un cumplido genuino, un chiste sencillo o un comentario ligero —casual y amable, sin peso comercial— sobre la persona, el lugar o algo en común. Lo que no cumple es un comentario que suena a inspección: contarle la mercancía o describir en frío lo que ve."}, {"id": "opening.arranque_sin_disculpa", "weight": 0.2, "regla_id": "opening.gasman", "description": "Cero disculpas, cero peticiones de permiso, cero minimizarse durante TODA la sesion, incluso despues de una respuesta seca."}, {"id": "mindset.regla_10_por_ciento", "weight": 0.1, "regla_id": "opening.energia_verbal", "description": "Sostiene energia y postura frente a la sequedad del cliente. No se encoge, no baja el volumen, no empieza a despedirse."}, {"id": "opening.curiosidad_abierta", "weight": 0.15, "regla_id": "opening.curiosidad_abierta", "description": "Deja abierto quién es el vendedor: abre sin presentarse, es decir, sin decir en primera persona su propio nombre ni el de la empresa que representa. Si no se presentó, este criterio se cumple. Dirigirse al cliente por su nombre o con 'don', 'señor' o 'sir' NO es presentarse. Que el cliente termine preguntando quién es confirma que funcionó, pero que no lo pregunte no le quita nada. Presentarse de entrada no se penaliza: simplemente no acredita este criterio."}]}$g$::jsonb WHERE id = '1.6' AND practice_script->>'version' = '2.0.0';
UPDATE public.nodes SET practice_script = $g${"notes": "BOSS del Mundo 3 — el más completo hasta ahora: integra M0 (apertura), M1 (temple ante sequedad analítica), M2 (historia + AIR) y M3 entero (RRR + capas + escucha + dolor). El Actor combina 4 mecánicas: estado de prisa, un bloqueo espejo, dolor por capas y datos laterales. pitch_prematuro es critical — la línea entre diagnóstico y receta es la frontera del mundo. 16 turnos y 6 mínimos: es una conversación larga de verdad.", "scope": {"skills_in_focus": ["discovery.preguntas_capas", "discovery.dolor_real", "discovery.escucha_activa", "mindset.rrr", "blocks.air", "story.historia_breve"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 16, "max_duration_seconds": 360, "min_turns_before_evaluation": 6}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil ANALÍTICO: preciso, algo reservado, respondes con datos y no con emociones, desconfías un poco de los vendedores porque varios te han hecho perder el tiempo. GUION DE LA SESIÓN: (1) Recibes la apertura con cortesía seca — hoy además andas algo APURADO (estado RRR: lo muestras en frases cortas y alguna mención de que traes pendientes). (2) En tus primeras 2-3 respuestas sueltas UN bloqueo reflejo suave: mire, la verdad ando corto de tiempo, o ya tengo con quién trabajo esto. Espejo AIR: si lo atraviesa bien, sigues; si lo debate, te enfrías. (3) Tienes un DOLOR REAL oculto — elige al azar: (tu proveedor actual te deja plantado con los pedidos cada quincena / tienes producto parado que no se mueve y te tiene el dinero muerto / te piden algo que tu proveedor no maneja). Lo revelas SOLO por capas: hechos → pista sutil en capa de experiencia (la palabra aunque) → dolor completo si excavan la pista. (4) MECÁNICA DE ESCUCHA: en tus respuestas de hechos regala UN dato lateral (un familiar en el negocio, un cambio reciente); si lo recogen, te abres más rápido — la capa 2 llega antes. (5) Si el vendedor lee tu prisa y la reconoce ajustando su ritmo, cooperas mejor. Si presenta producto en cualquier momento, te cierras con evasiva educada y la información se acaba. Tu techo emocional: cooperativo-interesado, nunca efusivo. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.\n\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor completa el diagnóstico de punta a punta ante un cliente analítico y apurado: apertura correcta y calibrada, historia breve corta con gancho, UN bloqueo atravesado con AIR, lectura del estado (prisa) reconocida y ajustada, descubrimiento por capas que recoge las pistas laterales y excava la pista del dolor hasta la revelación completa, cerrando con la confirmación verbal del dolor en palabras propias (entonces lo que más le está pegando es X, ¿cierto?). El scope se cubre cuando el dolor real quedó revelado por el cliente Y confirmado por el vendedor."}, "closing": {"message": "Diagnóstico completo: abriste, atravesaste el no, leíste su prisa, y excavaste hasta el dolor que no le cuenta a cualquiera. Un doctor de verdad. Vamos al desglose del mundo.", "message_incomplete": "Hasta aqui la sesion — un diagnostico de verdad no siempre se termina, pero siempre ensena. Vamos al desglose y te digo exactamente donde quedo la excavacion."}}, "version": "1.0.1", "i_do_type": "demo", "failure_criteria": [{"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "critical", "description": "Presenta producto en cualquier punto — incluso al descubrir el dolor. El diagnóstico termina donde empieza la receta, y la receta es del siguiente mundo.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "ignora_pistas", "regla_id": "discovery.escalera_capas", "severity": "major", "description": "Deja pasar la pista del dolor (el aunque) o los datos laterales de forma sistemática.", "espejo_de": "discovery.preguntas_capas"}, {"id": "debate_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Argumenta o negocia el bloqueo en lugar de atravesarlo con AIR.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "ignora_estado", "regla_id": "discovery.rrr", "severity": "major", "description": "El cliente muestra prisa clara y el vendedor avanza a su ritmo propio sin reconocerla ni ajustar.", "espejo_de": "mindset.rrr"}, {"id": "interrogatorio", "regla_id": "discovery.interrogatorio", "severity": "minor", "description": "Ráfagas de preguntas desconectadas de las respuestas."}, {"id": "kill_curriculum", "regla_id": "story.kill_curriculum", "severity": "minor", "description": "Historia breve inflada con credenciales.", "severity_override": {"razon": "incidental: error de otro paso", "default": "major"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Turnos largos ante un cliente con prisa."}], "success_criteria": [{"id": "discovery.preguntas_capas", "weight": 0.25, "regla_id": "discovery.escalera_capas", "description": "Descubrimiento con progresión de capas visible: hechos → experiencia → excavación de la pista (aunque...) hasta el dolor. Las preguntas nacen de las respuestas."}, {"id": "discovery.dolor_real", "weight": 0.2, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "El dolor completo fue revelado por el cliente Y confirmado verbalmente por el vendedor en sus propias palabras antes del cierre de la sesión."}, {"id": "discovery.escucha_activa", "weight": 0.15, "regla_id": "discovery.escalera_capas", "description": "Recoge al menos un dato lateral regalado por el cliente y construye sobre él con las palabras del cliente."}, {"id": "mindset.rrr", "weight": 0.15, "regla_id": "discovery.rrr", "description": "Lee la prisa del cliente, la reconoce verbalmente con naturalidad y ajusta su ritmo — directo y sin rodeos, respetando el estado."}, {"id": "blocks.air", "weight": 0.15, "regla_id": "blocks.air", "description": "Atraviesa el bloqueo con la secuencia completa: agree breve, ignore total del tema, resume por hilo natural."}, {"id": "story.historia_breve", "weight": 0.1, "regla_id": "story.quien_eres_por_que", "description": "Historia breve correcta en su momento: quién es + por qué está ahí, corta, con gancho."}]}$g$::jsonb WHERE id = '3.10' AND practice_script->>'version' = '1.0.0';
UPDATE public.nodes SET practice_script = $g${"notes": "v3.0.0 (oct-2026, doctrina de Emilio): la mala experiencia al llegar. Antes este nodo enseñaba a adelantar negativos al llegar; la doctrina cambió: con un cliente nuevo no se abre con negativos, y si el cliente saca una mala experiencia es una preocupación real, no un bloqueo. El espejo tiene cinco estados: recibirla en serio con motivo real y pregunta abre; ignorarla confirma; defenderse atrinchera; prometer en el aire no convence; inventar un cambio rompe la confianza.", "scope": {"skills_in_focus": ["blocks.mala_experiencia"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 6, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "A veces no llegas en blanco: el cliente ya trae una mala experiencia, con tu empresa o con vendedores como tú.\n\nEso no es un bloqueo. Un bloqueo es un no reflejo, sin razón. Esto tiene razón, y si lo ignoras, le confirmas que la tenía.\n\nMira lo que hago: lo acepto en serio, le doy el motivo real por el que vengo, y regreso a preguntar.", "first_message": "Él: ya me han fallado antes con las entregas, la verdad ya no les creo.\n\nEntiendo perfecto lo que me dice. De hecho, justo por eso me mandaron con usted: desde hace unos meses cambiamos cómo surtimos esta zona, y varios negocios que tenían el mismo problema ya regresaron. Pero primero tengo que ver si lo podemos atender. ¿Con quién está trabajando ahorita?"}, "you_do": {"prompt": "Eres el encargado de un negocio. Ya trabajaste antes con la empresa del vendedor, o con un proveedor como el suyo, y te fue mal. Elige UNA mala experiencia al azar: te dejaron sin producto varias veces / te cambiaron el precio sin avisar / el vendedor dejó de venir y nadie te avisó / te llegó producto en mal estado y nadie respondió. La sacas en tu PRIMERA o SEGUNDA respuesta, en cuanto sepas a qué viene, con molestia contenida, por ejemplo: \"Ah, ustedes... la vez pasada me dejaron sin producto tres semanas. La verdad ya no les creo.\" Es una preocupación REAL, no un no reflejo.\n\nREACCIONAS ASÍ:\n- Si el vendedor la acepta en serio (sin pelearla ni minimizarla), te da un motivo concreto y creíble de por qué viene ahora, y te devuelve la palabra con una pregunta sobre tu negocio: bajas la guardia un poco y contestas con un dato real. No te vuelves su amigo: sigues cauto.\n- Si la ignora y sigue como si nada (cambia de tema, sigue con lo suyo): te enfrías. \"¿Ve? Igualito que la otra vez.\" Y contestas cortante.\n- Si se defiende o discute (\"eso no fue culpa nuestra\", \"nosotros no somos así\"): te atrincheras y ya no quieres hablar del tema.\n- Si se disculpa de más o promete que él sí es diferente (\"perdón, pero yo sí soy diferente, se lo prometo\"): no te convence. \"Eso mismo me dijo el otro.\"\n- Si menciona un cambio o negocios que regresaron con detalles concretos, le das el beneficio de la duda; si es vago (\"ya mejoramos mucho\"), preguntas \"¿cómo qué?\".\n\nDespués de sacar tu queja, nunca preguntas tú qué vende ni a qué viene: la conversación la lleva él. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa y responde siempre de forma coherente con ese tipo. Responde en 1 o 2 frases.", "objective": "El vendedor recibe la mala experiencia del cliente como una preocupación real: la acepta sin pelearla ni minimizarla, da un motivo concreto de su visita, y le devuelve la palabra con una pregunta que regresa al diagnóstico. El scope se cubre cuando el cliente baja la guardia y contesta la pregunta con un dato de su negocio."}, "closing": {"message": "Eso es tratar una mala experiencia como lo que es: una preocupación de verdad. No la peleaste, no la ignoraste, le diste un motivo real y regresaste a preguntar. En El Cierre vas a aprender el FFF completo; hoy diste el primer paso. Vamos al detalle.", "message_incomplete": "Ahí lo dejamos. Vamos al desglose y te digo cómo recibiste su mala experiencia."}}, "version": "3.0.0", "i_do_type": "demo", "success_criteria": [{"id": "blocks.mala_experiencia", "weight": 1.0, "regla_id": "blocks.mala_experiencia_al_llegar", "description": "Recibe la mala experiencia como preocupación real, con sus tres piezas: (1) la acepta en serio, sin pelearla, minimizarla ni ignorarla; (2) da un motivo concreto y creíble de por qué viene ahora (qué cambió, o por qué lo mandaron con él); (3) regresa al diagnóstico con una pregunta sobre el negocio del cliente. Si el motivo es vago (\"ya mejoramos mucho\"), la pieza 2 queda a medias."}], "failure_criteria": [{"id": "la_trata_como_bloqueo", "regla_id": "objection.air_a_objecion", "severity": "major", "severity_override": {"default": "critical", "razon": "nodo de aprendizaje de La Historia Breve: el FFF completo llega en El Cierre"}, "espejo_de": "blocks.mala_experiencia", "description": "La ignora y sigue como si nada: cambia de tema o sigue con lo suyo, como si fuera un no reflejo. Le confirma al cliente que tenía razón."}, {"id": "se_defiende", "regla_id": "objection.discutir", "severity": "major", "severity_override": {"default": "critical", "razon": "nodo de aprendizaje de La Historia Breve: el FFF completo llega en El Cierre"}, "espejo_de": "blocks.mala_experiencia", "description": "Discute o justifica: \"eso no fue culpa nuestra\", \"nosotros no somos así\". Gana la discusión y pierde al cliente."}, {"id": "promesa_en_disculpa", "regla_id": "blocks.ataque_en_disculpa", "severity": "major", "description": "Se disculpa de más o promete que él sí es diferente (\"perdón, pero yo sí soy diferente\"): suena a excusa y no desarma nada."}, {"id": "cambio_inventado", "regla_id": "impulse.jones_vago", "severity": "critical", "description": "Menciona un cambio o negocios que regresaron que no puede sostener: cuando el cliente pregunta \"¿cómo qué?\", no tiene nada concreto."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promoción o motivo de venta."}]}$g$::jsonb WHERE id = '2.8' AND practice_script->>'version' = '2.0.1';
UPDATE public.nodes SET name = 'La Mala Experiencia al Llegar', description = $v$Cuando el cliente ya trae una mala experiencia, no es un bloqueo: la escuchas en serio, das el motivo real de tu visita y regresas a preguntar.$v$, field_mission = $v$Esta semana, cuando un cliente te saque una mala experiencia (con tu empresa o con otro proveedor), no la pelees ni la ignores: acéptala en serio, dale el motivo real de tu visita y regresa a preguntar por su negocio. Apunta qué te dijo, qué motivo le diste y qué te contestó.$v$ WHERE id = '2.8';

-- 5. node_skills que ya no se califican (después de los guiones).
DELETE FROM public.node_skills WHERE node_id = '4.16' AND skill_id = 'discovery.dolor_real';
DELETE FROM public.node_skills WHERE node_id = '4.16' AND skill_id = 'presentation.valor_personalizado';
DELETE FROM public.node_skills WHERE node_id = '5.12' AND skill_id = 'objections.no_defensivo';
DELETE FROM public.node_skills WHERE node_id = '5.15' AND skill_id = 'objections.no_defensivo';
DELETE FROM public.node_skills WHERE node_id = '2.8' AND skill_id = 'blocks.air';
DELETE FROM public.node_skills WHERE node_id = '2.8' AND skill_id = 'blocks.pre_emptive_strike';

-- 6. Tarjetas del 2.8.
UPDATE public.node_cards SET card_type = 'concept', title = $v$No siempre llegas en blanco$v$, body = $v$A veces el cliente ya trae una historia. Ya me fallaron con las entregas. Me cambiaron el precio. El vendedor dejó de venir.

Eso no es un bloqueo. Un bloqueo es un no reflejo, sin razón, y se atraviesa con AIR. Esto tiene razón. Si lo ignoras, le confirmas que la tenía.$v$, flip_back_text = NULL WHERE node_id = '2.8' AND card_order = 1;
UPDATE public.node_cards SET card_type = 'concept', title = $v$Escúchalo, da el motivo y pregunta$v$, body = $v$Tres piezas:

1. Lo aceptas en serio. Sin pelearlo y sin minimizarlo.
2. Le das el motivo real de tu visita: qué cambió, o por qué te mandaron con él.
3. Regresas a preguntar por su negocio.

Entiendo perfecto lo que me dice. De hecho, justo por eso me mandaron con usted: desde hace unos meses cambiamos cómo surtimos esta zona, y varios negocios que tenían el mismo problema ya regresaron. Pero primero tengo que ver si lo podemos atender. ¿Con quién está trabajando ahorita?$v$, flip_back_text = NULL WHERE node_id = '2.8' AND card_order = 2;
UPDATE public.node_cards SET card_type = 'why_it_works', title = $v$Tres maneras de arruinarlo$v$, body = $v$IGNORARLA. Seguir como si nada es tratar una preocupación real como un no reflejo: le confirmas que tenía razón.

DEFENDERTE. Eso no fue culpa nuestra. Ganas la discusión y pierdes al cliente.

PROMETER EN EL AIRE. Perdón, pero yo sí soy diferente. Suena a excusa. Y si mencionas un cambio, tiene que ser real: si te pregunta ¿cómo qué?, tienes que poder contestar.$v$, flip_back_text = NULL WHERE node_id = '2.8' AND card_order = 3;

-- Chequeos: si algo no quedó, se aborta todo.
DO $$
DECLARE n int;
BEGIN
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '2.10') <> '2.1.0' THEN RAISE EXCEPTION 'el nodo 2.10 no quedó en la versión 2.1.0'; END IF;
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '4.16') <> '1.1.0' THEN RAISE EXCEPTION 'el nodo 4.16 no quedó en la versión 1.1.0'; END IF;
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '5.12') <> '1.1.0' THEN RAISE EXCEPTION 'el nodo 5.12 no quedó en la versión 1.1.0'; END IF;
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '5.15') <> '1.1.0' THEN RAISE EXCEPTION 'el nodo 5.15 no quedó en la versión 1.1.0'; END IF;
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '7.0') <> '1.1.0' THEN RAISE EXCEPTION 'el nodo 7.0 no quedó en la versión 1.1.0'; END IF;
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '5.8') <> '1.0.1' THEN RAISE EXCEPTION 'el nodo 5.8 no quedó en la versión 1.0.1'; END IF;
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '7.2') <> '1.0.2' THEN RAISE EXCEPTION 'el nodo 7.2 no quedó en la versión 1.0.2'; END IF;
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '7.4') <> '1.0.1' THEN RAISE EXCEPTION 'el nodo 7.4 no quedó en la versión 1.0.1'; END IF;
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '1.6') <> '2.0.1' THEN RAISE EXCEPTION 'el nodo 1.6 no quedó en la versión 2.0.1'; END IF;
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '3.10') <> '1.0.1' THEN RAISE EXCEPTION 'el nodo 3.10 no quedó en la versión 1.0.1'; END IF;
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '2.8') <> '3.0.0' THEN RAISE EXCEPTION 'el nodo 2.8 no quedó en la versión 3.0.0'; END IF;
  IF (SELECT world_id_introduced FROM public.skills WHERE id = 'blocks.pre_emptive_strike') <> 4 THEN RAISE EXCEPTION 'el ataque preventivo no quedó en La Presentación'; END IF;
  IF (SELECT regla_id FROM public.skills WHERE id = 'objections.reframe') <> 'objection.fff' THEN RAISE EXCEPTION 'el FFF no quedó con su regla'; END IF;
  SELECT count(*) INTO n FROM public.nodes, jsonb_array_elements(practice_script->'success_criteria') c WHERE c->>'id' = 'objections.reframe' AND c->>'regla_id' <> 'objection.fff';
  IF n > 0 THEN RAISE EXCEPTION '% criterios de FFF siguen con otra regla', n; END IF;
  SELECT count(*) INTO n FROM public.nodes, jsonb_array_elements(practice_script->'success_criteria') c, public.skills s
   WHERE s.id = c->>'id' AND c ? 'regla_id' AND s.regla_id <> c->>'regla_id';
  IF n > 0 THEN RAISE EXCEPTION '% criterios con una regla distinta a la de su skill', n; END IF;
  SELECT count(*) INTO n FROM public.nodes, jsonb_array_elements(practice_script->'success_criteria') c
   WHERE NOT EXISTS (SELECT 1 FROM public.node_skills ns WHERE ns.node_id = nodes.id AND ns.skill_id = c->>'id');
  IF n > 0 THEN RAISE EXCEPTION '% criterios sin su fila en node_skills', n; END IF;
  SELECT count(*) INTO n FROM public.reglas r WHERE r.id IN ('blocks.mala_experiencia_al_llegar','impulse.factores')
   AND NOT EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND replace(d.body, '*', '') ILIKE '%' || r.cita_cerebro || '%');
  IF n > 0 THEN RAISE EXCEPTION '% reglas nuevas citan algo que no está en el Cerebro vigente', n; END IF;
  IF (SELECT count(*) FROM public.node_cards WHERE node_id = '2.8' AND title IN ('No siempre llegas en blanco','Escúchalo, da el motivo y pregunta','Tres maneras de arruinarlo')) <> 3 THEN RAISE EXCEPTION 'las tarjetas del 2.8 no quedaron'; END IF;
END $$;
